#!/bin/bash
# launch_ref.sh -- reference run (ref_mcm) of the hypothesis-1 trace @MODEL@/@CFG@ (decode layer 0 of one all-decode step):
# the 2026-11-04 70B 64 KiB distributed ref_mcm recipe (KERNEL_PARTITION + per-chiplet cursors + L2 TLB set hash 1, L1 TLB 64K
# 32 entries, L2 TLB 64K 1024 entries, merge caps unlimited, first-touch placement dump), instruction cap @CAP@
# (standard 1e10 when warp x 32 stays below it, else 0 with CAP_EXCEPTION.txt). Tree llm_sim_tree_pwcstat_l1fwd, 16 threads.
# Generated by llm_exp/scripts/h1_make_ref_arm.sh from h1_ref_launch_template.sh (docs/h1_llama70b_decode_batch_sweep.ko.md
# section 9). Waits for the chain's trace check (S6 TRACES PASS); the run itself is a child shell (ref_mcm/run.sh, no set -u).
# Run inside mcm-accelsim as uid 1035:
#   docker exec -d -u 1035:1035 mcm-accelsim bash /accel-sim/llm_exp/llm_hypothesis1/@MODEL@/@CFG@/sim/launch_ref.sh
# env DRY=1: preflight only.
set -u
P=/accel-sim/llm_exp/llm_hypothesis1/@MODEL@/@CFG@
X=$P/sim/ref_mcm
TREE=/accel-sim/llm_exp/llm_sim_tree_pwcstat_l1fwd
BIN=$TREE/gpu-simulator/bin/release/accel-sim.out
SO=$TREE/gpu-simulator/gpgpu-sim/lib/gcc-11.4.0/cuda-12020/release/libcudart.so
BIN_MD5=b4876c28ad2e290989c6460f86498e4c; SO_MD5=dbaed8e6c2c9b9ca20c23fc163cfe513
SRC_CFG=/accel-sim/llm_exp/experiments_distributed/llama70b_b4s256_L1seq64k_mcm/ref_mcm/gpgpusim.config
SRC_MD5=38ec08a8e4f8abfbae3bc0e1260508d1
TRACE=$P/traces/kernelslist.g
CHECK_LOG=$P/@CHECKLOG@
N_KERNELS=@NK@; MIN_COPIES=@MINCOPIES@; CAP=@CAP@; EXPECT_DIFF=@EXPECT_DIFF@
TH=${TH:-16}; DRY=${DRY:-0}
LOG=$P/sim/launch.log
log(){ echo "$(date '+%F %T') [h1_@CFG@_ref] $*" | tee -a $LOG; }
die(){ log "ABORT: $*"; echo "ABORT $*" >> $P/sim/status.txt; exit 1; }
md5(){ md5sum "$1" | awk '{print $1}'; }
exec {LK}>$P/sim/.launch.lock
flock -n $LK || { echo "another launch_ref.sh holds the lock"; exit 1; }

# ---------- gate: the chain's post-processed trace check must have passed ----------
log "waiting for $CHECK_LOG to report S6 TRACES PASS"
until grep -q '^S6 TRACES' $CHECK_LOG 2>/dev/null; do sleep 30; done
grep -q '^S6 TRACES PASS' $CHECK_LOG || die "trace check did not pass: $(grep '^S6 TRACES' $CHECK_LOG)"
log "trace check: $(grep '^S6 TRACES' $CHECK_LOG)"

# ---------- preflight ----------
[ "$(md5 $BIN)" = $BIN_MD5 ] || die "binary md5 $(md5 $BIN) != $BIN_MD5"
[ "$(md5 $SO)" = $SO_MD5 ] || die "libcudart.so md5 $(md5 $SO) != $SO_MD5"
[ "$(md5 $SRC_CFG)" = $SRC_MD5 ] || die "source ref_mcm config changed since 2026-11-04"
[ "$(diff $SRC_CFG $X/gpgpusim.config | grep -c '^[<>]')" = $EXPECT_DIFF ] || die "config differs from the 70B 64K ref_mcm config in an unexpected way"
if [ "$CAP" = 0 ]; then
  grep -qx -- '-gpgpu_max_insn 0' $X/gpgpusim.config && [ -s $X/CAP_EXCEPTION.txt ] || die "cap 0 without CAP_EXCEPTION.txt"
else
  grep -qx -- "-gpgpu_max_insn $CAP" $X/gpgpusim.config || die "config lacks -gpgpu_max_insn $CAP"
  diff $SRC_CFG $X/gpgpusim.config | grep -qx -- '< -gpgpu_max_insn 0' || die "only the cap line may change"
fi
for KV in "-gpgpu_page_size_policy 1" "-gpgpu_lasp_policy 4" "-gpgpu_cta_chiplet_cursor 1" "-gpgpu_l2_tlb_set_hash 1" \
          "-gpgpu_l1_tlb_64k_assoc 32" "-gpgpu_l2_tlb_64k_sets 128" "-gmmu_placement_dump ./placement_mcm.map"; do
  grep -qx -- "$KV" $X/gpgpusim.config || die "config lacks '$KV'"; done
[ -s $X/trace.config ] && [ -s $X/config_ampere_islip.icnt ] && [ -x $X/run.sh ] || die "trace.config / icnt / run.sh missing"
[ "$(grep -c '^MemcpyHtoD,' $TRACE)" -ge $MIN_COPIES ] && [ "$(grep -vc '^MemcpyHtoD,' $TRACE)" = $N_KERNELS ] \
  || die "trace list does not hold >= $MIN_COPIES copies + $N_KERNELS kernels"
for k in $(grep -v '^MemcpyHtoD,' $TRACE); do [ -s $P/traces/$k ] || die "missing trace file $k"; done
[ -e $X/run.log ] && die "run.log already exists -- refusing to overwrite"
log "preflight OK: kernels=$N_KERNELS copies=$(grep -c '^MemcpyHtoD,' $TRACE) cap=$CAP bin=$BIN_MD5 cfg=$(md5 $X/gpgpusim.config) trace=$(md5 $TRACE) threads=$TH dry=$DRY"
[ "$DRY" = 1 ] && { log "DRY run finished -- nothing launched"; exit 0; }

# ---------- run (child shell without set -u) ----------
echo "RUNNING ref_mcm $(date '+%F %T')" >> $P/sim/status.txt
log "ref_mcm start (threads $TH)"
TH=$TH bash $X/run.sh
cd $X
log "ref_mcm end: $(cat exit_code.txt 2>/dev/null)"
grep -q '^EXIT=0 ' exit_code.txt 2>/dev/null && grep -q '^\[PLACEMENT\] dump: ./placement_mcm.map' run.log && [ -s placement_mcm.map ] \
  && { echo "DONE $(date '+%F %T')" >> $P/sim/status.txt; log "ref_mcm finished with placement map"; } \
  || { echo "FAILED $(date '+%F %T')" >> $P/sim/status.txt; log "ref_mcm did not finish cleanly"; }
